
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_rda_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_rda", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.851576233622511e+02, -9.841764323875393e+01, -2.930957054067376e+01, 1.811649837536096e+01, 4.304221135119040e+01, 4.831742548412345e+01, 3.924584455830568e+01, 2.282302510265074e+01, 2.553971814874325e+01, 2.099800944234451e+01, 1.245028601370057e+01, 5.628093823420566e+00, 1.453137197169650e+00, 7.342535010367706e-01, 1.043692114211529e+00, 6.087113181735119e-01, 5.490192877866359e-01, 6.135940097240231e-01, 6.016406854244536e-01, 5.743256574795156e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


